package net.officefloor.hq.app.access;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordSettingChanged {
    public void record(@Val Setting setting, @Val ChangedBy by, Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + by.name() + " key=" + setting.key()
                + " value=" + (setting.value() == null ? "" : setting.value()));
    }
}
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// The settings form: the clerk limit, the most a clerk may settle a claim's due for (blank: no limit), and the
// floor, the least a claim's live due may be (1.00 until it is set), and the terms, the days after its date a claim is
// due by (14 until they are set), and the late percent, what an overdue claim's due gains of its figure for every
// full 30 days it is overdue (0.00 until it is set), and the policy date (blank: the sheet's today), before which a
// claim's live figures round half up and from which they round half to even. The value in force shows beside each. Saving
// sends only the settings whose field was touched since the last save.
const SETTINGS = [
  { key: 'clerk-limit', label: 'Clerk limit', placeholder: 'no limit', blank: true, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A clerk limit is an amount with up to two decimals, or blank for no limit' },
  { key: 'floor', label: 'Floor', placeholder: FLOOR_DEFAULT, blank: false, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A floor is an amount with up to two decimals' },
  { key: 'terms', label: 'Terms (days)', placeholder: TERMS_DEFAULT, blank: false, valid: DAYS, inputMode: 'numeric',
    invalid: 'Terms are a whole number of days' },
  { key: 'late-pct', label: 'Late percent', placeholder: LATE_PCT_DEFAULT, blank: false, valid: AMOUNT, inputMode: 'decimal',
    invalid: 'A late percent is a number with up to two decimals' },
  { key: 'policy-date', label: 'Policy date', placeholder: 'today', blank: true, valid: DATE, inputMode: 'text',
    invalid: 'A policy date is a date (yyyy-mm-dd), or blank for the sheet\'s today' },
] as const;

function SettingsPanel({ sheetId }: { sheetId: string; user: string }) {
  const settings = useSettings(sheetId);
  const [values, setValues] = useState<Record<string, string>>({});
  const [touched, setTouched] = useState<ReadonlySet<string>>(new Set());
  const [user] = useUser();
  const queryClient = useQueryClient();
  const current = (key: string) => (settings.data ?? []).find((s) => s.key === key)?.value ?? '';
  const touch = (key: string) => setTouched((t) => (t.has(key) ? t : new Set(t).add(key)));
  const save = useMutation({
    mutationFn: async (body: { keys: string[]; values: Record<string, string> }) => {
      const changes = SETTINGS.filter((s) => body.keys.includes(s.key));
      if (changes.length === 0) throw new Error('Change a setting first');
      for (const s of changes) {
        const value = (body.values[s.key] ?? '').trim();
        if (value === '' ? !s.blank : !s.valid.test(value)) throw new Error(s.invalid);
      }
      for (const s of changes) {
        await putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`,
          { key: s.key, value: (body.values[s.key] ?? '').trim(), by: user ?? '' });
      }
    },
    onSuccess: async () => {
      setTouched(new Set());
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
    },
  });
  const submit = useSubmitOnce(save);
  return (
    <section data-testid="settings-panel">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ keys: [...touched], values });
        }}
      >
        {SETTINGS.map((s) => (
          <span key={s.key}>
            <label>
              {s.label}{' '}
              <input
                data-testid={`setting-${s.key}`}
                inputMode={s.inputMode}
                placeholder={s.placeholder}
                value={values[s.key] ?? ''}
                onFocus={() => touch(s.key)}
                onChange={(e) => {
                  const value = e.target.value;
                  setValues((v) => ({ ...v, [s.key]: value }));
                  touch(s.key);
                  save.reset();
                }}
              />
            </label>{' '}
            <span>
              In force: <strong data-testid={`setting-${s.key}-current`}>{current(s.key)}</strong>
            </span>{' '}
          </span>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <p data-testid="settings-error" role="alert">
            {save.error.message}
          </p>
        )}
      </form>
      {settings.isError && (
        <p data-testid="settings-load-error" role="alert">
          {settings.error.message}
        </p>
      )}
    </section>
  );
/** The late percent a sheet starts with, until it is set. */
export const LATE_PCT_DEFAULT = '0.00';

/** The sheet's late charge as of its today: its terms and its late percent (0.00 until it is set); with its
 *  policy date (its today while blank) and the numbered claims' dates, which decide how each claim rounds. Undefined
 *  until the sheet's today is known. */
export function useLate(sheetId: string): Late | undefined {
  const settings = useSettings(sheetId).data;
  const pct = settings?.find((s) => s.key === 'late-pct')?.value ?? LATE_PCT_DEFAULT;
  const policy = settings?.find((s) => s.key === 'policy-date')?.value ?? '';
  const termsDays = useTermsDays(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId).data;
  const dateOfNumber = new Map<number, string>();
  for (const c of claims ?? []) if (c.number != null) dateOfNumber.set(c.number, c.date);
  return today === undefined ? undefined
    : { today, termsDays, pctHundredths: toHundredths(pct), policyDate: policy === '' ? today : policy, dateOfNumber };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened; none for a draft or a void claim. */
  number: number | null;
  /** The due fixed when the claim was settled; none while live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The signed-in user who opened the claim; none when it was never opened. They cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals `statedDue` (none: n/a). */
  stated: boolean;
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; none for any other claim. */
  corrects: number | null };

/** Whether a claim counts toward claimed, due and every total: only OPEN and SETTLED claims do, and a held
      </td>
    </tr>
  );
}

// The period a claim belongs to: the one whose dates contain its date; blank when none does.
function ClaimPeriod({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: { date: string } }) {
  const periods = usePeriods(sheetId);
  return <span data-testid="claim-period">{periodOn(periods.data ?? [], claim.date)?.name ?? ''}</span>;
}

export const contributions = [
  SheetBody.fill({ order: 7, Component: PeriodsPanel }),
  ClaimCells.fill({ order: 30, Component: ClaimPeriod }),
];

