  const current = (key: string) => (settings.data ?? []).find((s) => s.key === key)?.value ?? '';
  const touch = (key: string) => setTouched((t) => (t.has(key) ? t : new Set(t).add(key)));
  const save = useMutation({
    mutationFn: async (body: { keys: string[]; values: Record<string, string> }) => {
      const changes = SETTINGS.filter((s) => body.keys.includes(s.key));
      if (changes.length === 0) throw new Error('Change a setting first');
      for (const s of changes) {
        const value = (body.values[s.key] ?? '').trim();
        if (value === '' ? !s.blank : !s.valid.test(value)) throw new Error(s.invalid);
      }
      for (const s of changes) {
        await putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`,
          { key: s.key, value: (body.values[s.key] ?? '').trim(), by: user ?? '' });
      }
    },
    onSuccess: async () => {
      setTouched(new Set());
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
    },
  });
  const submit = useSubmitOnce(save);
  return (
    <section data-testid="settings-panel">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ keys: [...touched], values });
        }}
      >
        {SETTINGS.map((s) => (
          <span key={s.key}>
            <label>
              {s.label}{' '}
              <input
                data-testid={`setting-${s.key}`}
                inputMode={s.inputMode}
                placeholder={s.placeholder}
                value={values[s.key] ?? ''}
                onFocus={() => touch(s.key)}
                onChange={(e) => {
                  const value = e.target.value;
                  setValues((v) => ({ ...v, [s.key]: value }));
                  touch(s.key);
                  save.reset();
                }}
              />
            </label>{' '}
            <span>
              In force: <strong data-testid={`setting-${s.key}-current`}>{current(s.key)}</strong>
            </span>{' '}
          </span>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <p data-testid="settings-error" role="alert">
            {save.error.message}
          </p>
        )}
      </form>
      {settings.isError && (
        <p data-testid="settings-load-error" role="alert">
          {settings.error.message}
        </p>
      )}
    </section>
  );
/** The late percent a sheet starts with, until it is set. */
export const LATE_PCT_DEFAULT = '0.00';

/** The sheet's late charge as of its today: its terms and its late percent (0.00 until it is set); with its
 *  policy date (its today while blank) and the numbered claims' dates, which decide how each claim rounds. Undefined
 *  until the sheet's today is known. */
export function useLate(sheetId: string): Late | undefined {
  const settings = useSettings(sheetId).data;
  const pct = settings?.find((s) => s.key === 'late-pct')?.value ?? LATE_PCT_DEFAULT;
  const policy = settings?.find((s) => s.key === 'policy-date')?.value ?? '';
  const termsDays = useTermsDays(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const claims = useClaims(sheetId).data;
  const dateOfNumber = new Map<number, string>();
  for (const c of claims ?? []) if (c.number != null) dateOfNumber.set(c.number, c.date);
  return today === undefined ? undefined
    : { today, termsDays, pctHundredths: toHundredths(pct), policyDate: policy === '' ? today : policy, dateOfNumber };
}
